2128	/**
2129	 * Reverse a money side-effect that a job committed up-front but never delivered.
2130	 * Server actions charge/credit the wallet before enqueuing the worker job (so the
2131	 * UI reflects the change immediately); if the job then fails terminally the money
2132	 * must be unwound or the customer is charged for a resize that never happened
2133	 * (up) or keeps a downgrade credit for hardware they still have (down).
2134	 * Idempotent per job: guarded by the RECONCILED audit marker so a re-run can't
2135	 * double-reverse.
2136	 */
2137	async function reconcileFailedJob(job: Job) {
2138	  if (job.type === "DISK_EXPAND") return reconcileFailedDiskExpand(job);
2139	  if (job.type === "ASSIGN_DEDICATED_IP") return reconcileFailedDedicatedIp(job);
2140	  if (job.type !== "RESIZE") return;
2141	  const p = (job.payload ?? {}) as { prorateCents?: number; direction?: "up" | "down" };
2142	  const cents = p.prorateCents ?? 0;
2143	  if (cents <= 0 || !job.serverId) return;
2144	
2145	  // Idempotency: skip if we already reversed this exact job.
2146	  const already = await db.auditLog.findFirst({
2147	    where: { action: "server.resize.reconcile", detail: { contains: `job=${job.id}` } },
2148	  });
2149	  if (already) return;
2150	
2151	  const server = await db.server.findUnique({ where: { id: job.serverId }, select: { userId: true, hostname: true } });
2152	  if (!server) return;
2153	
2154	  try {
2155	    if (p.direction === "up") {
2156	      // Upgrade charge never delivered → refund the prorated charge.
2157	      await db.$transaction([
2158	        db.user.update({ where: { id: server.userId }, data: { balanceCents: { increment: cents } } }),
2159	        db.walletTransaction.create({
2160	          data: { userId: server.userId, amountCents: cents, description: `Refund: failed upgrade — ${server.hostname}` },
2161	        }),
2162	      ]);
2163	    } else if (p.direction === "down") {
2164	      // Downgrade credit was given but hardware unchanged → claw the credit back.
2165	      // Guarded so it can never drive the balance negative; if the customer already
2166	      // spent it, we log and leave it (best-effort — they keep a small windfall).
2167	      await db.$transaction(async (tx) => {
2168	        await debitWallet(tx, server.userId, cents);
2169	        await tx.walletTransaction.create({
2170	          data: { userId: server.userId, amountCents: -cents, description: `Reversed downgrade credit (resize failed) — ${server.hostname}` },
2171	        });
2172	      });
2173	    }
2174	    await db.auditLog.create({
2175	      data: { userId: server.userId, action: "server.resize.reconcile", detail: `job=${job.id} dir=${p.direction} cents=${cents}` },
2176	    });
2177	  } catch (e: any) {
2178	    // InsufficientBalanceError on a down-reversal is expected/acceptable; record it.
2179	    await db.auditLog.create({
2180	      data: { userId: server.userId, action: "server.resize.reconcile.uncharged", detail: `job=${job.id} dir=${p.direction} cents=${cents} :: ${e?.message ?? e}` },
2181	    }).catch(() => {});
