21	async function ensureChainLocal(chain: string) {
22	  try {
23	    await iptables(["-t", "nat", "-N", chain]);
24	  } catch {
25	    /* chain exists */
26	  }
27	  // Ensure PREROUTING jumps to our chain exactly once — this is the path for
28	  // EXTERNAL clients (real customers) reaching a NAT guest's forwarded port.
29	  try {
30	    await iptables(["-t", "nat", "-C", "PREROUTING", "-j", chain]);
31	  } catch {
32	    await iptables(["-t", "nat", "-A", "PREROUTING", "-j", chain]);
33	  }
34	  // Also jump from OUTPUT for HOST-LOCAL traffic aimed at our own public IP.
35	  // PREROUTING DNAT never fires for packets a process on THIS box originates, so
36	  // the platform's own ops that connect to <PUBLIC_IP>:<forwarded-port> — SSL
37	  // issuance, migration remediation, backups, the Claude backfill — were hitting
38	  // the host's own (empty) port and getting ECONNREFUSED for every NAT server.
39	  // Scoping the jump to `-d <PUBLIC_IP>` means only traffic addressed to the
40	  // public IP is redirected; host-local :port traffic to anything else is
41	  // untouched, and the shared DNAT rules only match ports that actually forward.
42	  const publicIp = (process.env.PUBLIC_IP ?? "").trim();
43	  if (publicIp) {
44	    try {
45	      await iptables(["-t", "nat", "-C", "OUTPUT", "-d", publicIp, "-j", chain]);
46	    } catch {
47	      await iptables(["-t", "nat", "-A", "OUTPUT", "-d", publicIp, "-j", chain]);
48	    }
49	  }
