84	/** Dispatch: local iptables for the primary (the only node the worker itself
85	 *  runs on), the remote agent for everyone else. */
86	function natHostFor(node: { isPrimary: boolean } & AgentNode, chain: string): NatHost {
87	  return node.isPrimary ? iptablesHost(chain) : agentNatHost(node, chain);
88	}
