184	/**
185	 * For callers that must not be re-queued by a sync failure (server DELETE runs
186	 * this after the row is gone, so a throw dies on "Server not found" on retry and
187	 * the sync is never re-attempted — H5's aggravating factor).
188	 *
189	 * It still never claims success: the failure is logged in full and returned, so
190	 * the caller can surface it. What it will not do is convert a networking problem
191	 * into a stuck job that hides it.
192	 */
193	export async function syncPortForwardsBestEffort(context: string): Promise<Error | null> {
194	  try {
195	    await syncPortForwards();
196	    return null;
197	  } catch (e: any) {
198	    console.error(`[nat] port-forward sync FAILED after ${context} — forwarding may be wrong: ${e?.message ?? e}`);
199	    return e instanceof Error ? e : new Error(String(e));
200	  }
201	}
