11	const execFileP = promisify(execFile);
12	
13	/**
14	 * Is this address already the target of a live DNAT rule on ITS OWN node?
15	 * Some infrastructure (the shared-hosting node, VM 200) reaches its dedicated
16	 * IP entirely through a whole-IP DNAT rule to an internal address — it has no
17	 * OVH Virtual MAC at all, so the MAC-based check above cannot see it. A real
18	 * incident: this exact IP was one query away from being handed to a game
19	 * server because "no Virtual MAC bound" was mistaken for "free" — it was
20	 * actively carrying production hosting traffic via `iptables -t nat`. Treat
21	 * any address with a live DNAT target as claimed, unconditionally.
22	 *
23	 * Dispatches by node: the primary's own local iptables (unchanged), or the
24	 * owning node's agent for anyone else — this used to always check the LOCAL
25	 * host regardless of which node `address` actually belongs to, which for a
26	 * non-primary node's pool checks the wrong machine's kernel entirely and
27	 * could double-allocate an address that's actually already claimed there.
28	 */
29	async function hasLiveDnatRule(node: NodeRow, address: string): Promise<boolean> {
30	  if (!node.isPrimary) {
31	    try {
32	      return await agentHasLiveDnatRule(node, address);
33	    } catch {
34	      // Agent unreachable/not configured — same fail-open reasoning as the
35	      // local case below: a false "not claimed" is recoverable (the Virtual
36	      // MAC check and the existing DB row are the other guards), a sync that
37	      // silently no-ops for an entire node's pool forever is not.
38	      return false;
39	    }
40	  }
41	  try {
42	    const { stdout } = await execFileP("iptables", ["-t", "nat", "-S", "PREROUTING"]);
43	    return stdout.split("\n").some((line) => line.includes(`-d ${address}/32`) && line.includes("-j DNAT"));
44	  } catch {
45	    // iptables unreadable (permissions, not present, sandboxed test env) — fail
46	    // closed is wrong here (it would make every sync a no-op); fail to "not
47	    // claimed by this specific check" and rely on the Virtual MAC check plus
48	    // the existing DB row remaining authoritative for anything already tracked.
49	    return false;
50	  }
51	}
