127	/** Resolve the Node a dedicated-IP operation should act against: the id passed
128	 *  in explicitly, else the primary node — same fallback shape as
129	 *  worker/index.ts's nodeFor(), so single-node callers need no changes at all. */
130	async function resolveNode(nodeId?: string): Promise<NodeRow | null> {
131	  if (nodeId) {
132	    return db.node.findUnique({ where: { id: nodeId }, select: NODE_ROW_SELECT });
133	  }
134	  return db.node.findFirst({ where: { isPrimary: true }, select: NODE_ROW_SELECT });
