137	/** Is the right provider API even configured for this node? Dispatches by
138	 *  provider so a Hetzner-hosted server never silently falls through to
139	 *  checking whether OVH happens to be configured (the real bug this fixes —
140	 *  worker/index.ts used to gate purely on ovhConfigured(), with no node
141	 *  awareness at all). */
142	export async function dedicatedIpProviderConfigured(nodeId?: string): Promise<boolean> {
143	  const node = await resolveNode(nodeId);
144	  if (!node) return false;
145	  return node.provider === "HETZNER" ? hetznerConfigured() : ovhConfigured();
146	}
