148	/**
149	 * Pull additional/failover IPv4 addresses routed to a node's server from its
150	 * provider and upsert them into the pool. The host's own primary IP is never
151	 * poolable. Defaults to the primary (OVH) node when no `nodeId` is given —
152	 * identical behavior to before this file supported more than one node.
153	 */
154	export async function syncDedicatedIpPool(nodeId?: string): Promise<{ imported: number; total: number }> {
155	  if (SANDBOX) return { imported: 0, total: 0 };
156	  const node = await resolveNode(nodeId);
157	  if (!node || !node.providerServerId) return { imported: 0, total: 0 };
158	
159	  if (node.provider === "HETZNER") return syncHetznerPool(node);
160	  return syncOvhPool(node);
161	}
