163	async function syncOvhPool(node: NodeRow): Promise<{ imported: number; total: number }> {
164	  if (!ovhConfigured()) return { imported: 0, total: 0 };
165	  const SERVER = node.providerServerId!;
166	  const primary = node.publicIp;
167	  const blocks: string[] = await ovhApi.ips();
168	  let imported = 0;
169	  for (const block of blocks) {
170	    if (block.includes(":")) continue; // IPv6 handled separately
171	    let info: any;
172	    try {
173	      info = await ovhApi.ipInfo(block);
174	    } catch {
175	      continue;
176	    }
177	    if (info?.routedTo?.serviceName !== SERVER) continue;
178	    if (info?.type !== "failover" && info?.type !== "additional") continue; // exclude the primary "dedicated" host IP
179	    // A /32 block is a single usable IP == the block minus the mask.
180	    const address = block.split("/")[0];
181	    if (address === primary) continue;
182	    const existing = await db.dedicatedIp.findUnique({ where: { address } });
183	    if (!existing) {
184	      // An IP that already has a Virtual MAC bound to it on OVH's side is already
185	      // in active use by SOME VM — possibly one this app never created a Server
186	      // row for (e.g. internal infrastructure provisioned directly via the OVH
187	      // API, like the cold-email relay). A genuinely free IP has no bound MAC
188	      // yet. Importing it as FREE anyway let a real customer server collide with
189	      // an unrelated VM's network identity — never assign an IP that's already
190	      // claimed at the network layer, regardless of whether our DB knows about it.
191	      if (await findVirtualMacForIp(SERVER, address)) continue;
192	      if (await hasLiveDnatRule(node, address)) continue;
193	      // Every IP this function imports is, by construction, a spare address
194	      // OVH says is routed to us and not yet claimed at the network layer — the
195	      // pool customer orders draw from. Internal-use IPs (the cold-email relay,
196	      // an owner-operated site, the shared-hosting node) are rare, hand-provisioned
197	      // one-offs marked INTERNAL by an admin after the fact; this sync has no way
198	      // to tell them apart from a genuinely free customer IP and must not try —
199	      // it always imports as CUSTOMER (the schema default, stated here for clarity).
200	      await db.dedicatedIp.create({ data: { address, ovhBlock: block, nodeId: node.id, status: "FREE", purpose: "CUSTOMER" } });
201	      imported++;
202	    }
203	  }
204	  const total = await db.dedicatedIp.count({ where: { nodeId: node.id } });
205	  return { imported, total };
206	}
