208	/**
209	 * Hetzner side of the sync. Hetzner's `/ip` listing already returns exactly
210	 * the single additional IPs on the account (no failover/additional type
211	 * distinction to filter like OVH's `/ip` does) — every entry not equal to the
212	 * node's own main `publicIp` is poolable.
213	 */
214	async function syncHetznerPool(node: NodeRow): Promise<{ imported: number; total: number }> {
215	  if (!hetznerConfigured()) return { imported: 0, total: 0 };
216	  let imported = 0;
217	  const ips: Array<{ ip: string }> = await hetznerApi.ips().catch(() => []);
218	  for (const entry of ips) {
219	    const address = entry.ip;
220	    if (!address || address === node.publicIp) continue;
221	    const existing = await db.dedicatedIp.findUnique({ where: { address } });
222	    if (existing) continue;
223	    if (await hasLiveDnatRule(node, address)) continue;
224	    await db.dedicatedIp.create({
225	      data: { address, ovhBlock: "", nodeId: node.id, status: "FREE", purpose: "CUSTOMER" },
226	    });
227	    imported++;
228	  }
229	  const total = await db.dedicatedIp.count({ where: { nodeId: node.id } });
230	  return { imported, total };
231	}
