254	/** Find the OVH Virtual MAC currently bound to an IP, if any. */
255	async function findVirtualMacForIp(server: string, address: string): Promise<string | null> {
256	  const macs: string[] = await ovh("GET", `/dedicated/server/${server}/virtualMac`).catch(() => []);
257	  for (const m of macs) {
258	    const ips: string[] = await ovh("GET", `/dedicated/server/${server}/virtualMac/${m}/virtualAddress`).catch(() => []);
259	    if (ips.includes(address)) return m;
260	  }
261	  return null;
262	}
