264	/**
265	 * Claim a free IP for a server and set it up so the VM can use it — an OVH
266	 * Virtual MAC for an OVH-node IP, or nothing extra for a Hetzner-node IP
267	 * (Hetzner additional IPs route straight to the server's real MAC, no
268	 * separate MAC object to create). Returns the address + a MAC (OVH only,
269	 * empty string for Hetzner) + gateway, or null if none available.
270	 *
271	 * `nodeId` should be the server's OWN node — pass it explicitly from a
272	 * caller that already resolved it (e.g. worker/index.ts's `nodeFor(server)`);
273	 * omitted, this falls back to the primary node, identical to this file's
274	 * pre-multi-node behavior.
275	 */
276	export async function allocateDedicatedIp(
277	  serverId: string,
278	  vmid: number,
279	  nodeId?: string,
280	): Promise<{ address: string; virtualMac: string; gateway: string } | null> {
281	  if (SANDBOX) {
282	    // Hand out a synthetic dedicated IP without any provider call or pool mutation.
283	    return { address: sandboxIp(vmid), virtualMac: sandboxMac(vmid), gateway: "198.51.100.254" };
284	  }
285	  // Idempotent per server: PROVISION can retry (up to MAX_ATTEMPTS). If this
286	  // server already holds a fully-allocated dedicated IP, return it instead of
287	  // claiming a second pool IP — re-claiming would leak an IP and P2002 on the
288	  // unique DedicatedIp.serverId. An OVH row also needs a bound Virtual MAC to
289	  // count as "done"; a Hetzner row is done once ASSIGNED (no MAC step).
290	  const mine = await db.dedicatedIp.findUnique({ where: { serverId }, include: { node: true } });
291	  if (mine && mine.status === "ASSIGNED" && (mine.node.provider === "HETZNER" || mine.virtualMac)) {
292	    return { address: mine.address, virtualMac: mine.virtualMac ?? "", gateway: await gatewayFor(mine.node, mine.address) };
293	  }
294	
295	  const node = await resolveNode(nodeId);
296	  if (!node) return null;
297	  if (!(await dedicatedIpProviderConfigured(node.id))) return null;
298	
299	  // Atomically claim a FREE ip belonging to THIS node's pool. Excluding
300	  // purpose: INTERNAL here is a second, independent guard (alongside the
301	  // sync-time checks above) against ever handing an admin-marked internal IP
302	  // to a customer server.
303	  const claim = await db.$transaction(async (tx) => {
304	    const ip = await tx.dedicatedIp.findFirst({
305	      where: { status: "FREE", purpose: "CUSTOMER", nodeId: node.id },
306	      orderBy: { createdAt: "asc" },
307	    });
308	    if (!ip) return null;
309	    await tx.dedicatedIp.update({ where: { id: ip.id }, data: { status: "PENDING", serverId } });
310	    return ip;
311	  });
312	  if (!claim) return null;
313	
314	  try {
315	    if (node.provider === "HETZNER") {
316	      await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "ASSIGNED" } });
317	      return { address: claim.address, virtualMac: "", gateway: await gatewayFor(node, claim.address) };
318	    }
319	    // OVH branch — unchanged mechanics, just keyed off this node's own service name.
320	    const SERVER = node.providerServerId!;
321	    let mac = await findVirtualMacForIp(SERVER, claim.address);
322	    if (!mac) {
323	      // Creation is asynchronous (returns a task) — kick it off then poll.
324	      await ovhApi.createVirtualMac(SERVER, claim.address, `nxeon-${vmid}`);
325	      for (let i = 0; i < 40 && !mac; i++) {
326	        await new Promise((r) => setTimeout(r, 3000));
327	        mac = await findVirtualMacForIp(SERVER, claim.address);
328	      }
329	    }
330	    if (!mac) throw new Error("Virtual MAC not bound after creation (OVH task still pending)");
331	    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "ASSIGNED", virtualMac: mac } });
332	    return { address: claim.address, virtualMac: mac, gateway: ovhGatewayFor(node.publicIp) };
333	  } catch (e) {
334	    // Roll the claim back to FREE on failure
335	    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "FREE", serverId: null, virtualMac: null } });
336	    throw e;
337	  }
338	}
