340	/**
341	 * The gateway a VM should use for this IP. OVH: the well-known "/24 -> .254"
342	 * convention, same for every additional IP on that node. Hetzner: NOT a
343	 * fixed formula — Hetzner assigns a distinct gateway per single additional
344	 * IP (confirmed against Hetzner's own docs this session: additional IP
345	 * SUBNETS route via the server's main IP with no separate gateway, but
346	 * single additional IPs each come with their own gateway address) — read it
347	 * from Hetzner's own `/ip/{ip}` response rather than guessing a formula.
348	 * NOTE: the exact response field name below (`gateway`) hasn't been verified
349	 * against a real Hetzner additional IP yet (none exist in the pool at the
350	 * time this was written) — confirm it the first time this path actually
351	 * runs, before trusting it for a real customer's network config.
352	 */
353	async function gatewayFor(node: NodeRow, address: string): Promise<string> {
354	  if (node.provider === "OVH") return ovhGatewayFor(node.publicIp);
355	  try {
356	    const info = await hetznerApi.ipInfo(address);
357	    if (info?.ip?.gateway) return info.ip.gateway as string;
358	  } catch {
359	    /* fall through */
360	  }
361	  return node.publicIp; // best-effort fallback; see doc comment above
362	}
