364	/** Release a server's dedicated IP back to the pool (deletes the OVH Virtual
365	 *  MAC for an OVH-node IP; a Hetzner-node IP just gets un-assigned, no
366	 *  separate MAC object to delete). */
367	export async function releaseDedicatedIp(serverId: string): Promise<void> {
368	  if (SANDBOX) return;
