101	  if (typeof name !== "string" || name.length === 0) throw new Error("A name is required.");
102	  if (name.length > MAX_NAME_LEN) throw new Error("Name is too long.");
103	  if (name.includes("/") || name.includes("\0")) throw new Error("Name contains invalid characters.");
104	  if (name === "." || name === "..") throw new Error("That name is not allowed.");
105	  return name;
106	}
