104	/** Parse Claude's plan reply into a validated list of steps, or null. */
105	function parsePlan(reply: string): PlanStep[] | null {
106	  const start = reply.indexOf("[");
107	  const end = reply.lastIndexOf("]");
108	  if (start === -1 || end === -1 || end < start) return null;
109	  let raw: unknown;
110	  try {
111	    raw = JSON.parse(reply.slice(start, end + 1));
112	  } catch {
113	    return null;
114	  }
115	  if (!Array.isArray(raw)) return null;
116	  const steps: PlanStep[] = [];
117	  for (const item of raw) {
118	    if (typeof item === "string") {
119	      const cmd = item.trim();
120	      if (cmd) steps.push({ cmd, intent: "" });
121	    } else if (item && typeof item === "object") {
122	      const anyItem = item as Record<string, unknown>;
123	      const cmd = String(anyItem.cmd ?? anyItem.command ?? "").trim();
124	      const intent = String(anyItem.intent ?? anyItem.description ?? "").trim();
125	      if (cmd) steps.push({ cmd, intent });
126	    }
127	  }
128	  return steps.length ? steps : null;
129	}
