138	export async function claudeBuild(job: Job): Promise<void> {
139	  const payload = (job.payload ?? {}) as { buildId?: string };
140	  const buildId = payload.buildId;
141	  if (!buildId) throw new Error("claudeBuild: missing buildId in job payload");
142	
143	  const build = await db.claudeBuild.findUnique({
144	    where: { id: buildId },
145	    include: { server: { include: { dedicatedIp: true, node: true } } },
146	  });
147	  if (!build) throw new Error(`claudeBuild: build ${buildId} not found`);
148	  const server = build.server;
149	
150	  // Terminal builds are never re-processed by a stray/duplicate job.
151	  if (build.status === "DONE" || build.status === "FAILED") return;
152	
153	  if (SANDBOX) {
154	    // Simulate the plan-then-approve flow with no Anthropic call and no SSH.
155	    if (!build.approved) {
156	      await db.claudeBuild.update({
157	        where: { id: buildId },
158	        data: {
159	          status: "AWAITING_APPROVAL",
160	          plan: JSON.stringify([{ cmd: "echo sandbox build", intent: "Sandbox simulated step" }]),
161	        },
162	      });
163	    } else {
164	      await db.claudeBuild.update({
165	        where: { id: buildId },
166	        data: {
167	          status: "DONE",
168	          steps: 1,
169	          log: truncate((build.log ?? "") + "\n[sandbox] simulated build completed\n", MAX_LOG_CHARS),
170	        },
171	      });
172	      await db.notification
173	        .create({
174	          data: {
175	            userId: build.userId,
176	            title: `Claude finished building on ${server?.hostname ?? "your server"}`,
177	            body: build.prompt.slice(0, 140),
178	            href: `/dashboard/build`,
179	          },
180	        })
181	        .catch(() => {});
182	    }
183	    return;
184	  }
185	
186	  // Everything is gated on an effective owner key + a reachable RUNNING server.
187	  const owner = await db.user.findUnique({
188	    where: { id: build.userId },
189	    select: { anthropicKeyEnc: true },
190	  });
191	  const apiKey = effectiveKeyFor(owner);
192	  if (!apiKey) {
193	    await failBuild(buildId, build.log ?? "", "No Anthropic API key available for the owner.");
194	    return;
195	  }
196	  if (!server || server.status !== "RUNNING") {
197	    await failBuild(buildId, build.log ?? "", "The server is not running.");
198	    return;
199	  }
200	  if (!connectionTarget(server) || !serverRootPassword(server)) {
201	    await failBuild(buildId, build.log ?? "", "The server is not reachable (no IP or root password).");
202	    return;
203	  }
204	
205	  if (!build.approved) {
206	    await planPhase(buildId, build.status, build.prompt, build.log ?? "", apiKey);
207	  } else {
208	    await executePhase(buildId, build.prompt, build.plan, build.log ?? "", server);
209	  }
210	}
