212	/** Phase 1: ask Claude for a plan, store it, and await owner approval. */
213	async function planPhase(
214	  buildId: string,
215	  status: string,
216	  prompt: string,
217	  priorLog: string,
218	  apiKey: string
219	): Promise<void> {
220	  // Only plan for a not-yet-planned build; ignore duplicate jobs otherwise.
221	  if (status !== "QUEUED" && status !== "PLANNING") return;
222	
223	  await db.claudeBuild.update({ where: { id: buildId }, data: { status: "PLANNING" } });
224	
225	  const messages: ClaudeMessage[] = [
226	    { role: "user", content: `Goal: ${prompt}\n\nProduce the plan now as a JSON array of {"cmd","intent"} steps.` },
227	  ];
228	
229	  let reply: string;
230	  try {
231	    reply = await askClaude(apiKey, messages, PLAN_SYSTEM_PROMPT, { maxTokens: 4096, timeoutMs: 90_000 });
232	  } catch (e: any) {
233	    await failBuild(buildId, priorLog, `Planning failed: ${e?.message ?? e}`);
234	    return;
235	  }
236	
237	  const plan = parsePlan(reply);
238	  if (!plan) {
239	    await failBuild(buildId, priorLog, "Claude did not return a usable plan for this goal.");
240	    return;
241	  }
242	
243	  const capped = plan.slice(0, CLAUDE_MAX_COMMANDS);
244	  await db.claudeBuild.update({
245	    where: { id: buildId },
246	    data: { status: "AWAITING_APPROVAL", plan: JSON.stringify(capped) },
247	  });
248	}
