250	/** Phase 2: execute the OWNER-APPROVED plan over SSH. */
251	async function executePhase(
252	  buildId: string,
253	  prompt: string,
254	  planJson: string | null,
255	  priorLog: string,
256	  server: SftpServer & { hostname: string | null }
257	): Promise<void> {
258	  let plan: PlanStep[] = [];
259	  try {
260	    const parsed = JSON.parse(planJson ?? "[]");
261	    if (Array.isArray(parsed)) {
262	      plan = parsed
263	        .map((s: any) => ({ cmd: String(s?.cmd ?? s ?? "").trim(), intent: String(s?.intent ?? "") }))
264	        .filter((s: PlanStep) => s.cmd);
265	    }
266	  } catch {
267	    plan = [];
268	  }
269	
270	  if (plan.length === 0) {
271	    await failBuild(buildId, priorLog, "No approved plan to execute.");
272	    return;
273	  }
274	
275	  await db.claudeBuild.update({ where: { id: buildId }, data: { status: "RUNNING" } });
276	
277	  const commands = plan.slice(0, CLAUDE_MAX_COMMANDS);
278	  let log = priorLog;
279	  const append = async (chunk: string, steps: number) => {
280	    log = truncate(log + chunk, MAX_LOG_CHARS);
281	    await db.claudeBuild.update({ where: { id: buildId }, data: { log, steps } });
282	  };
283	
284	  await append(`# Goal: ${prompt}\n# Executing approved plan (${commands.length} command(s))\n\n`, 0);
285	
286	  let steps = 0;
287	  let finalStatus: "DONE" | "FAILED" = "DONE";
288	
289	  try {
290	    // One connection for the whole approved plan, not one sshpass subprocess
291	    // per command — also the only way this can reach a server on a non-primary
292	    // node (host/port come from connectionTarget(), never the guest's private IP).
293	    await withServerSsh(server, async (conn) => {
294	      for (const step of commands) {
295	        const command = step.cmd;
296	
297	        // Defense-in-depth: even an approved plan is re-checked against the denylist.
298	        if (isForbidden(command)) {
299	          await append(`\n$ ${command}\n[nxeon] Skipped — blocked by the safety denylist.\n`, steps);
300	          continue;
301	        }
302	
303	        steps += 1;
304	        const { output, failed } = await runCommand(conn, command);
305	        const shown = truncate(output, MAX_OUTPUT_CHARS);
306	        await append(`\n$ ${command}\n${shown}\n`, steps);
307	
308	        if (failed) {
309	          await append(`\n[nxeon] Command failed — stopping execution.\n`, steps);
310	          finalStatus = "FAILED";
311	          break;
312	        }
313	      }
314	    });
315	  } catch (e: any) {
316	    await append(`\n[nxeon] Build error: ${e?.message ?? e}\n`, steps);
317	    finalStatus = "FAILED";
318	  }
319	
320	  await db.claudeBuild.update({ where: { id: buildId }, data: { status: finalStatus, steps } });
321	
322	  try {
323	    await db.notification.create({
324	      data: {
325	        userId: (await db.claudeBuild.findUnique({ where: { id: buildId }, select: { userId: true } }))!.userId,
326	        title:
327	          finalStatus === "DONE"
328	            ? `Claude finished building on ${server.hostname}`
329	            : `Claude build failed on ${server.hostname}`,
330	        body: prompt.slice(0, 140),
331	        href: `/dashboard/build`,
332	      },
333	    });
334	  } catch {
335	    /* notification is best-effort */
336	  }
337	}
