1	/**
2	 * Nxeon in-portal web terminal — standalone PTY websocket backend.
3	 *
4	 * A tiny long-running Node process (run with tsx, NOT bundled by Next) that
5	 * bridges a browser xterm.js websocket to a real SSH shell on a customer VM:
6	 *
7	 *   browser  ──ws──▶  terminal-server  ──ssh2──▶  customer VM (root shell / PTY)
8	 *   (xterm.js)        (holds nothing)             (the actual shell)
9	 *
10	 * SECURITY MODEL
11	 *  - The websocket is authorized ONLY by a short-lived encrypted token minted by
12	 *    app/api/terminal/token (POST, session-checked, ownership-checked). This
13	 *    process re-verifies that token, then RE-LOADS the server and RE-CHECKS
14	 *    ownership (userId match) and status (RUNNING) against the database before
15	 *    it opens any SSH connection. A token names one user + one server and is
16	 *    valid for 60 seconds.
17	 *  - The VM's root password is fetched here (lib/sftp serverRootPassword, which
18	 *    decrypts rootPasswordEnc) and used to authenticate the SSH connection. It
19	 *    NEVER crosses the websocket and is NEVER logged.
20	 *  - Listens on 127.0.0.1 only — it is meant to sit behind nginx, which proxies
21	 *    /terminal-ws (with WebSocket upgrade headers) to this port.
22	 *
23	 * LIMITS ENFORCED PER SESSION
24	 *  - 15s to authenticate the token + establish the SSH shell, else the socket is
25	 *    closed.
26	 *  - 10 min idle (no bytes either direction) → closed.
27	 *  - 60 min hard cap on total session duration → closed.
28	 *
29	 * SANDBOX (NXEON_SANDBOX=1): no SSH is ever opened. After the same token +
30	 * ownership checks, a friendly simulated shell is piped (banner + echo) so the
31	 * staging environment works end to end without real VMs.
32	 *
33	 * ENV (read from the same /opt/nxeon/.env as the web app, via systemd
34	 * EnvironmentFile; a best-effort .env loader below covers manual runs):
35	 *   AUTH_SECRET              shared secret — must match the web app (required)
36	 *   DATABASE_URL             Prisma connection (required)
37	 *   PUBLIC_IP                for NAT servers' host resolution (lib/sftp)
38	 *   NXEON_TERMINAL_WS_PORT   listen port (default 8901)
39	 *   NXEON_TERMINAL_WS_HOST   listen address (default 127.0.0.1)
40	 *
41	 * Run: npx tsx terminal-server/index.ts
42	 */
43	import { readFileSync } from "node:fs";
44	import { resolve } from "node:path";
45	import type { IncomingMessage } from "node:http";
46	
47	// --- Best-effort .env loader (systemd already provides these; this only fills
48	// gaps for manual `npx tsx` runs, and NEVER overrides an existing env var). ---
49	function loadDotEnv(): void {
50	  if (process.env.AUTH_SECRET && process.env.DATABASE_URL) return;
51	  try {
52	    const text = readFileSync(resolve(process.cwd(), ".env"), "utf8");
53	    for (const raw of text.split("\n")) {
54	      const line = raw.trim();
55	      if (!line || line.startsWith("#")) continue;
56	      const eq = line.indexOf("=");
57	      if (eq === -1) continue;
58	      const key = line.slice(0, eq).trim();
59	      if (key in process.env) continue;
60	      let val = line.slice(eq + 1).trim();
61	      if (
62	        (val.startsWith('"') && val.endsWith('"')) ||
63	        (val.startsWith("'") && val.endsWith("'"))
64	      ) {
65	        val = val.slice(1, -1);
66	      }
67	      process.env[key] = val;
68	    }
69	  } catch {
70	    /* no .env file — rely on the real environment */
71	  }
72	}
73	loadDotEnv();
