318	function parseClientMsg(raw: Buffer, isBinary: boolean): ClientMsg | null {
319	  if (isBinary) return null;
320	  let obj: unknown;
321	  try {
322	    obj = JSON.parse(raw.toString("utf8"));
323	  } catch {
324	    return null;
325	  }
326	  if (!obj || typeof obj !== "object") return null;
327	  const m = obj as Record<string, unknown>;
328	  if (m.type === "data" && typeof m.data === "string") {
329	    return { type: "data", data: m.data };
330	  }
331	  if (m.type === "resize") {
332	    return { type: "resize", cols: clampDim(m.cols, 80), rows: clampDim(m.rows, 24) };
333	  }
334	  return null;
335	}
