337	/**
338	 * Sandbox shell: a friendly simulated terminal. No SSH — just a banner and a
339	 * local echo of what the user types, so the whole UX works on staging.
340	 */
341	function startSandboxShell(
342	  ws: WebSocket,
343	  bump: () => void,
344	  shutdown: (reason: string, notify?: string) => void
345	): void {
346	  const nl = "\r\n";
347	  const prompt = "\x1b[32mnxeon-sandbox\x1b[0m:\x1b[34m~\x1b[0m# ";
348	  const banner =
349	    `\x1b[36mNxeon sandbox terminal\x1b[0m${nl}` +
350	    `This is a simulated shell on the staging environment — no real SSH` +
351	    ` connection is made.${nl}` +
352	    `Type anything and it will be echoed back. On production this is a real` +
353	    ` root shell where you can run \x1b[1mclaude\x1b[0m.${nl}${nl}`;
354	
355	  if (ws.readyState === WebSocket.OPEN) ws.send(banner + prompt);
356	
357	  let line = "";
358	  ws.on("message", (raw: Buffer, isBinary: boolean) => {
359	    bump();
360	    const msg = parseClientMsg(raw, isBinary);
361	    if (!msg || msg.type !== "data") return; // ignore resize in the sim
362	    for (const ch of msg.data) {
363	      if (ch === "\r" || ch === "\n") {
364	        let out = nl;
365	        if (line.trim()) out += `you typed: ${line}${nl}`;
366	        line = "";
367	        if (ws.readyState === WebSocket.OPEN) ws.send(out + prompt);
368	      } else if (ch === "\x7f" || ch === "\b") {
369	        if (line.length > 0) {
370	          line = line.slice(0, -1);
371	          if (ws.readyState === WebSocket.OPEN) ws.send("\b \b");
372	        }
373	      } else if (ch >= " ") {
374	        line += ch;
375	        if (ws.readyState === WebSocket.OPEN) ws.send(ch);
376	      }
377	    }
378	  });
379	
380	  // Keep the same guarantee that the socket eventually closes.
381	  void shutdown;
382	}
