10	/**
11	 * Reachable on every host regardless of portal mode: Next internals, the API
12	 * surface every portal's own client code calls (chat SSE, uploads, etc.),
13	 * and the auth utility pages every login form links to. Everything else is
14	 * scoped to exactly one portal below.
15	 */
16	function isUniversallyAllowed(pathname: string): boolean {
17	  return (
18	    pathname.startsWith("/_next") ||
19	    pathname.startsWith("/api/") ||
20	    pathname === "/favicon.ico" ||
21	    pathname.startsWith("/.well-known/") ||
22	    pathname === "/forgot-password" ||
23	    pathname === "/reset-password" ||
24	    // Both portal layouts redirect a staff/admin account without 2FA here to
25	    // enroll (enforce_staff_2fa) — account security settings aren't
26	    // customer-specific, and blocking this would stand between a legitimate
27	    // staff member and the one page that lets them satisfy the requirement.
28	    pathname === "/dashboard/settings"
29	  );
30	}
31	
32	/**
33	 * Confines the admin/staff hostnames to exactly their own portal.
34	 *
35	 * app/admin/layout.tsx and app/staff/layout.tsx already refuse the WRONG
36	 * direction — /admin and /staff 404 on any host that isn't their own
37	 * NXEON_ADMIN_HOSTS/NXEON_STAFF_HOSTS. But nothing stopped the REVERSE: the
38	 * admin/staff hostnames proxy to the exact same Next.js backend as the main
39	 * site, so /dashboard, /login, /register, and every marketing page were
40	 * equally reachable there too — confirmed live 2026-09-02, a customer's full
41	 * dashboard (wallet, deploy, domains) loading on the staff-only subdomain.
42	 * Not a data leak (they only ever saw their own account), but it defeats the
43	 * point of a separate, minimal, operations-only surface, and reduces
44	 * whatever "hard to guess" value the admin subdomain has by leaving it fully
45	 * browsable/indexable as a second copy of the public site.
46	 *
47	 * Together with the two layouts' existing checks this makes the mapping
48	 * exact: admin host <-> /admin only, staff host <-> /staff only, every other
49	 * host <-> everything except /admin and /staff.
50	 */
51	export function middleware(req: NextRequest) {
52	  const host = (req.headers.get("host") ?? "").toLowerCase().split(":")[0];
53	  const { pathname } = req.nextUrl;
54	
55	  const adminHosts = hostList(process.env.NXEON_ADMIN_HOSTS);
56	  const staffHosts = hostList(process.env.NXEON_STAFF_HOSTS);
57	  const isAdminHost = adminHosts.length > 0 && adminHosts.includes(host);
58	  const isStaffHost = staffHosts.length > 0 && staffHosts.includes(host);
59	
60	  // An admin impersonating a customer (lib/auth.ts's setImpersonation) needs to
61	  // browse the FULL customer app — /dashboard, /checkout, etc. — from their own
62	  // admin host, since impersonation swaps identity without changing host. Only
63	  // ADMIN can ever hold this cookie (EMPLOYEE/staff can never impersonate — see
64	  // setImpersonation's own role check), so this only ever loosens the admin
65	  // host. We only check the cookie's PRESENCE here, not its signature/validity
66	  // — that's exactly as strong as this gate needs to be: a forged or expired
67	  // token still gets fully re-verified by impersonating()/currentUser() at the
68	  // page/action layer, so a bad cookie here just falls back to "no session",
69	  // never to unauthorized access.
70	  const impCookieName = `${process.env.NXEON_COOKIE_NAME ?? "nxeon_session"}_imp`;
71	  const isImpersonating = isAdminHost && req.cookies.has(impCookieName);
72	
73	  if ((isAdminHost || isStaffHost) && !isImpersonating) {
74	    const ownPrefix = isAdminHost ? "/admin" : "/staff";
75	    const ownLogin = isAdminHost ? "/admin/login" : "/staff/login";
76	
77	    if (!isUniversallyAllowed(pathname) && !pathname.startsWith(ownPrefix)) {
78	      // The shared /login page (and any stray redirect to it — logout()
79	      // always sends there, regardless of who's logging out) lands on this
80	      // host's own dedicated login instead of 404ing a signed-out visitor.
81	      if (pathname === "/login") {
82	        const url = req.nextUrl.clone();
83	        url.pathname = ownLogin;
84	        return NextResponse.redirect(url);
85	      }
86	      // The bare root — where someone typing/bookmarking just the hostname
87	      // lands — goes to the portal itself rather than 404ing. The admin
88	      // vhost happens to have its own nginx-level `location = / return 302
89	      // /admin` that already covered this there (confirmed live), but the
90	      // staff vhost has no equivalent, so its root 404'd under this same
91	      // isolation logic. Handling it here covers both hosts the same way
92	      // regardless of nginx config: an authenticated visit shows the portal,
93	      // an unauthenticated one gets bounced on to ownLogin by the layout's
94	      // own existing redirect — no new auth logic needed either way.
95	      if (pathname === "/") {
96	        const url = req.nextUrl.clone();
97	        url.pathname = ownPrefix;
98	        return NextResponse.redirect(url);
99	      }
100	      return new NextResponse("Not found.", { status: 404 });
101	    }
102	  }
103	
104	  // Server Components have no built-in way to read the current pathname —
105	  // app/admin/layout.tsx and app/staff/layout.tsx need it to special-case
106	  // their own /login sub-route (public, no Shell, no auth redirect) without
107	  // a redirect loop. Set on the REQUEST (not the response) so headers() in a
108	  // downstream Server Component actually sees it.
109	  const requestHeaders = new Headers(req.headers);
110	  requestHeaders.set("x-pathname", pathname);
111	  return NextResponse.next({ request: { headers: requestHeaders } });
112	}
