/** Best-effort live progress write onto the running Job row (never throws). */
async function reportJobProgress(jobId: string, progress: number, step: string) {
  try {
    await db.job.update({
      where: { id: jobId },
      data: { progress: Math.max(0, Math.min(100, Math.round(progress))), step },
    });
  } catch (e) {
    console.error("[restore] job progress update failed", e);
  }
}

